import hashlib
import json
PUBLIC_
PUBLIC_E=65537

def canonical_payload(payload: dict) -> bytes:
    return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")

def verify_signature(payload: dict, signature_hex: str) -> bool:
    try: signature=int(signature_hex,16)
    except (TypeError,ValueError): return False
    digest_int=int.from_bytes(hashlib.sha256(canonical_payload(payload)).digest(),"big")
    return pow(signature,PUBLIC_E,PUBLIC_N)==digest_int
